#include <iostream>
using namespace std;

int main() {
    // Without endl - everything on one line
    cout << "Hello ";
    cout << "World ";
    cout << "Together!";

    cout << endl;

    // With endl - each on its own line
    cout << "Hello" << endl;
    cout << "World" << endl;
    cout << "Separate!" << endl;

    return 0;
}

